    @m2m_interface_availability_check
    def perform_delta_recommissioning(self, delta_file, nidd_info, wait_for_completion=True, timeout=300,
                                      should_activate=True):
        mo_info_list = self._convert_json_to_mo_info_list(delta_file, nidd_info)
        operation = self.local_client.perform_delta_recommissioning(mo_info_list=mo_info_list, timeout=timeout,
                                                                    should_activate=should_activate)

        if wait_for_completion:
            method_name = "get_status_of_perform_delta_recommissioning" if should_activate else \
                "get_status_of_perform_delta_recommissioning_without_activation"

            return poll_status(instance=self.local_client,
                               method_name=method_name,
                               operation_id=operation["id"], timeout=timeout)

        return operation

    def _convert_json_to_mo_info_list(self, delta_file, nidd_info):
        if os.path.isfile(delta_file):
            with open(delta_file, 'r') as file:
                data = json.load(file)
        else:
            data = json.loads(delta_file)

        mo_info_list = []
        for item in data:
            mo_info = self._create_mo_info_list_item(item=item, nidd_info=nidd_info)
            mo_info_list.append(mo_info)

        return mo_info_list

    def _create_mo_info_list_item(self, item, nidd_info):
            dist_name = item['distName']
            operation = item['operation']
            class_name = self._get_class_name_from_dist_name(dist_name=dist_name)
            mo_info = {"className": class_name, "distName": dist_name, "operationType": operation}

            if operation != "delete":
                mo_info['payload'] = self._prepare_payload_from_parameters(item=item, class_name=class_name,
                                                                           nidd_info=nidd_info)

            return mo_info

    def _prepare_payload_from_parameters(self, item, class_name, nidd_info):
        payload = {}
        for param in item['parameters']:
            if param["operation"] == "delete":
                payload[param["parameterName"]] = None
            else:
                param_value = param["value"]
                if isinstance(param_value, list) and len(param_value) == 1 and isinstance(param_value[0], dict):
                    max_occurrence = self._get_max_occurrence_of_list_parameter(class_name=class_name,
                                                                                param_name=param["parameterName"],
                                                                                nidd_info=nidd_info)
                    if max_occurrence == 1:
                        payload[param["parameterName"]] = param['value'][0]
                    else:
                        payload[param["parameterName"]] = param['value']
                else:
                    payload[param["parameterName"]] = param['value']

        return json.dumps(payload)

    @staticmethod
    def _get_max_occurrence_of_list_parameter(class_name, param_name, nidd_info):
        parameter_info = list(filter(lambda x: x['class_name'] == class_name, nidd_info))[0]["parameters"]
        for name, definition in parameter_info.items():
            if name == param_name:
                try:
                    return int(definition["complex_parameter_def"]["max_occurs"])
                except AttributeError:
                    return int(definition["simple_list_parameter_def"]["max_occurs"])

        raise Exception(f'Cannot find the parameter {param_name} under {class_name}')

    @staticmethod
    def _get_class_name_from_dist_name(dist_name):
        return dist_name.split("/")[-1].split("-")[0]

