    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value, nidd_info, should_activate=True, timeout=300):
        if operation == "delete":
            item = {"distName": dist_name,
                    "operation": "update",
                    "parameters": [{"parameterName": parameter,
                                    "operation": operation,
                                    "value": value}]}
        else:
            item = {"distName": dist_name,
                    "operation": operation,
                    "parameters": [{"parameterName": parameter,
                                    "operation": operation,
                                    "value": value}]}
        mo_info_list = [self._create_mo_info_list_item(item=item, nidd_info=nidd_info)]
        operation = self.local_client.perform_delta_recommissioning(mo_info_list=mo_info_list, timeout=timeout,
                                                                    should_activate=should_activate)
        method_name = "get_status_of_perform_delta_recommissioning" if should_activate else \
            "get_status_of_perform_delta_recommissioning_without_activation"
        return poll_status(instance=self.local_client,
                            method_name=method_name,
                            operation_id=operation["id"], timeout=timeout)

    def perform_object_recommissioning(self, dist_name, parameter, operation, nidd_info, should_activate=True, timeout=300):
        item = {"distName": dist_name, "operation": operation, "parameters": parameter}
        mo_info_list = [self._create_mo_info_list_item(item=item, nidd_info=nidd_info)]
        operation = self.local_client.perform_delta_recommissioning(mo_info_list=mo_info_list, timeout=timeout,
                                                                    should_activate=should_activate)
        method_name = "get_status_of_perform_delta_recommissioning" if should_activate else \
            "get_status_of_perform_delta_recommissioning_without_activation"
        return poll_status(instance=self.local_client,
                            method_name=method_name,
                            operation_id=operation["id"], timeout=timeout)

